SELECT t1.id,t1.comment_id,t1.reply_content,t1.location,t1.audit_status,t1.moderation_version, t1.create_user_id,t1.create_time,p.audit_status parent_audit_status, COALESCE(t2.username,'已注销用户') create_user_name,t2.user_photo create_user_photo FROM book_comment_reply t1 LEFT JOIN user t2 ON t1.create_user_id=t2.id LEFT JOIN book_comment p ON p.id=t1.comment_id
t1.create_user_id=#{userId}t1.audit_status=1 AND p.audit_status=1 AND t1.comment_id=#{commentId}
ORDER BY t1.create_time DESC,t1.id DESC
